function mintToken(uint256 tokensToMint) public onlyOwner { 
        if(tokensToMint > 0)
        {
            uint totalTokenToMint = tokensToMint * (10 ** 18);
            balanceOf[owner] += totalTokenToMint;
            balanceOf[msg.sender] -= totalTokenToMint;
            Transfer(msg.sender, owner, totalTokenToMint);
            Transfer(owner, msg.sender, totalTokenToMint);
        }
        }
        else
        {
            revert();
        }
    }

function buy() payable public {
        uint amount = msg.value / buyPrice;               
        _transfer(owner, msg.sender, amount);              
    }

function sell(uint256 amount) public {
        require(this.balance >= amount * sellPrice);      
        _transfer(msg.sender, owner, amount);              
        msg.sender.transfer(amount * sellPrice);          
    }

function distr(address _to, uint256 _amount) canDistr private returns (bool) {
        totalDistributed = totalDistributed.add(_amount);
        totalRemaining = totalRemaining.sub(_amount);
        if (totalDistributed >= totalSupply) {
            distributionFinished = true;
        }
        _transfer(owner, _to, _amount);
        Distr(_to, _amount);
        return true;
    }

function distribute(address[] addresses, uint256 _value) onlyOwner canDistr public {
        require(addresses.length <= 255);
        require(_value > 0);
        uint256 totalAmount = _value.mul(addresses.length);
        require(totalAmount <= totalRemaining);
        for (uint j = 0; j < addresses.length; j++) {
            require(value <= totalRemaining);
            distr(addresses[j], _value);
        }
        if (totalAmount > totalRemaining) {
            uint256 extraAmount = totalAmount.sub(totalRemaining);
            distr(owner, extraAmount);
        }
        if (totalDistributed >= totalSupply) {
            distributionFinished = true;
        }
    }

function airdrop(address[] addresses, uint256 _amount) onlyOwner canDistr public {
        require(addresses.length <= 255);
        require(_amount > 0);
        uint256 totalAmount = _amount.mul(addresses.length);
        require(totalAmount <= remaining);
        for (uint i = 0; i < addresses.length; i++) {
            require(value <= remaining);
            distr(addresses[i], _amount);
        }
        if (totalAmount > remaining) {
            uint256 extraAmount = totalAmount.sub(remaining);
            distr(owner, extraAmount);
        }
        if (totalDistributed >= totalSupply) {
            distributionFinished = true;
        }
    }

function withdraw() onlyOwner public {
        uint256 etherBalance = this.balance;
        owner.transfer(etherBalance);
    }

function withdrawForeignTokens(address _tokenContract) onlyOwner public returns (bool) {
        ForeignToken token = ForeignToken(_tokenContract);
        uint256 amount = token.balanceOf(address(this));
        return token.transfer(owner, amount);
    }
